-- 웹 정상화(#701): 검사표 '원문 줄 빠짐'(source_lost) 실패 공고의 원본·지점별 공고·저장 주소·화면 표시·중복 식별 대조(Lee 2026-11-26 지시 2~5).
-- 읽기 전용(데이터 변경 없음). 대상: 자동 처리 기준 시각(2026-11-01 09:15 UTC) 이후 수집·관리자 공고 중 검사표 source_lost가 실패인 공고(관리자 숨김 제외) — 공고 번호를 고정하지 않는다.
-- 원문·연락처·주소·원본 URL은 찍지 않는다: 원본 글은 md5 앞 8자리(같은 글끼리 묶기용), 지점 위치 식별자도 md5 앞 8자리, 나머지는 참/거짓·건수·공고 번호만.
-- JOB 줄: 같은 원본 글(source_url)에서 나온 공고 묶음, 근무지 줄 수, 지점 위치 식별자(normalized_address), 같은 글·같은 지점 식별자를 가진 다른 공고(= 중복 후보), 연락처 유무,
--          원문의 근무지 이름표 줄(<성·시>:주소) 수와 그 줄이 이 공고/같은 글의 다른 공고 지점 식별자로 이어지는 수(admin_location_key — 입구 branch_key와 같은 함수).
-- LOST 줄: 검사표가 빠졌다고 적은 줄마다 — 이름표 줄 여부, 만드는 쪽이 뺀 이유(detail_fill.dropped), 이 공고 근무지 주소와 같음, 이 공고/다른 지점 식별자와 같음, 상세요강에 그대로 있음.
-- 실행: ops-run-sql.yml(master, Lee 계정 수동, name=read-source-lost-branches). 출력은 실행 로그에만.
set transaction read only;
\pset tuples_only on
\pset format unaligned
with t as (select j.id, j.active, j.source_url, j.source_text, j.employer_phone, j.contact_zalo from public.local_jobs j cross join lateral jsonb_array_elements(coalesce(j.ocr_check->'inspect'->'items', '[]'::jsonb)) i where j.origin in ('crawler', 'admin') and j.created_at > '2026-11-01T09:15:00Z' and not j.admin_hidden and i->>'key' = 'source_lost' and coalesce((i->>'ok')::boolean, true) = false), g as (select t.id, s.id as sib from t join public.local_jobs s on s.source_url = t.source_url and s.id <> t.id where nullif(t.source_url, '') is not null), w as (select job_id, normalized_address as k, raw_address as a from public.job_work_locations), src as (select t.id, regexp_replace(trim(l), '^[^0-9:]{2,25}:[[:space:]]*', '') as v from t cross join lateral regexp_split_to_table(replace(coalesce(t.source_text, ''), chr(13), ''), chr(10)) l where trim(l) ~ '^[^0-9:]{2,25}:[[:space:]]*[^[:space:]]') select 'JOB ' || t.id || ' active=' || t.active || ' src=' || coalesce(left(md5(nullif(t.source_url, '')), 8), 'none') || ' group=[' || coalesce((select string_agg(g.sib::text, ',' order by g.sib) from g where g.id = t.id), '') || ']' || ' locs=' || (select count(*) from w where w.job_id = t.id) || ' keys=[' || coalesce((select string_agg(coalesce(left(md5(w.k), 8), 'null'), ',' order by w.k) from w where w.job_id = t.id), '') || ']' || ' same_src_same_key=[' || coalesce((select string_agg(distinct g.sib::text, ',') from g join w a on a.job_id = g.id join w b on b.job_id = g.sib and b.k = a.k where g.id = t.id), '') || ']' || ' contact=' || (coalesce(public.job_phone_digits(t.employer_phone), '') <> '' or coalesce(trim(t.contact_zalo), '') <> '') || ' src_label_lines=' || (select count(*) from src where src.id = t.id) || ' to_own_key=' || (select count(*) from src where src.id = t.id and exists (select 1 from w where w.job_id = t.id and w.k = public.admin_location_key(src.v))) || ' to_sibling_key=' || (select count(*) from src where src.id = t.id and exists (select 1 from g join w on w.job_id = g.sib where g.id = t.id and w.k = public.admin_location_key(src.v))) || ' to_no_job=' || (select count(*) from src where src.id = t.id and not exists (select 1 from w where w.k = public.admin_location_key(src.v) and (w.job_id = t.id or w.job_id in (select g.sib from g where g.id = t.id)))) from t order by t.id;
with t as (select j.id, j.description, j.ocr_check, (i->>'detail') as detail from public.local_jobs j cross join lateral jsonb_array_elements(coalesce(j.ocr_check->'inspect'->'items', '[]'::jsonb)) i where j.origin in ('crawler', 'admin') and j.created_at > '2026-11-01T09:15:00Z' and not j.admin_hidden and i->>'key' = 'source_lost' and coalesce((i->>'ok')::boolean, true) = false), sib as (select t.id, s.id as sib from t join public.local_jobs a on a.id = t.id join public.local_jobs s on s.source_url = a.source_url and s.id <> a.id where nullif(a.source_url, '') is not null), l as (select t.id, n, trim(x) as line, regexp_replace(trim(x), '^[^0-9:]{2,25}:[[:space:]]*', '') as v, t.description, t.ocr_check from t cross join lateral unnest(string_to_array(t.detail, ' / ')) with ordinality as u(x, n)) select 'LOST ' || l.id || '#' || l.n || ' len=' || length(l.line) || ' label=' || (l.line ~ '^[^0-9:]{2,25}:[[:space:]]*[^[:space:]]') || ' dropped_reason=' || coalesce((select string_agg(distinct d->>'reason', ',') from jsonb_array_elements(coalesce(l.ocr_check->'detail_fill'->'dropped', '[]'::jsonb)) d where trim(d->>'line') = l.line), 'none') || ' own_addr=' || exists (select 1 from public.job_work_locations w where w.job_id = l.id and lower(trim(w.raw_address)) = lower(l.v)) || ' own_key=' || exists (select 1 from public.job_work_locations w where w.job_id = l.id and w.normalized_address = public.admin_location_key(l.v)) || ' sibling_key=[' || coalesce((select string_agg(distinct sib.sib::text, ',') from sib join public.job_work_locations w on w.job_id = sib.sib where sib.id = l.id and w.normalized_address = public.admin_location_key(l.v)), '') || ']' || ' in_desc=' || (position(lower(l.line) in lower(coalesce(l.description, ''))) > 0) from l order by l.id, l.n;
